import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/configuration.md","filePath":"en/guide/configuration.md"}`),a={name:`en/guide/configuration.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>This page describes Zotero PDF2zh <strong>v4.1.1</strong> configuration (including v4.1.0 features).</p><h2 id="plugin-settings" tabindex="-1">Plugin Settings <a class="header-anchor" href="#plugin-settings" aria-label="Permalink to “Plugin Settings”">​</a></h2><p>Open <strong>Tools → PDF2zh Preferences</strong> in Zotero.</p><h3 id="python-server-ip" tabindex="-1">Python Server IP <a class="header-anchor" href="#python-server-ip" aria-label="Permalink to “Python Server IP”">​</a></h3><ul><li>Default: <code>http://127.0.0.1:8890</code></li><li>If you change <code>server.py --port</code>, update the plugin URL accordingly.</li><li>v4.1.0 binds the Server to <code>127.0.0.1</code> by default. For intentional remote deployment, start it explicitly with:</li></ul><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Remote access</p><p><code>0.0.0.0</code> exposes the Server to other devices reachable on the current network. Configure firewall rules and enable it only when remote access is intended.</p></div><h3 id="translation-engine" tabindex="-1">Translation Engine <a class="header-anchor" href="#translation-engine" aria-label="Permalink to “Translation Engine”">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>pdf2zh 1.x</th><th>pdf2zh_next 2.x</th></tr></thead><tbody><tr><td>Status</td><td>Legacy compatibility</td><td><strong>Recommended</strong></td></tr><tr><td>Config</td><td><code>config.json</code></td><td><code>config.toml</code></td></tr><tr><td>Custom fonts</td><td>Supported</td><td>Primarily upstream font-family selection</td></tr><tr><td>Dual layouts</td><td>Basic</td><td>LR side-by-side / TB alternating pages</td></tr><tr><td>OCR / table / glossary features</td><td>Fewer</td><td>More complete</td></tr><tr><td>DeepSeek V4 Thinking</td><td>N/A</td><td>Supported in 2.9.0+</td></tr></tbody></table><p>Use <strong>pdf2zh_next</strong> unless you specifically depend on a legacy feature.</p><h2 id="llm-api-configuration" tabindex="-1">LLM API Configuration <a class="header-anchor" href="#llm-api-configuration" aria-label="Permalink to “LLM API Configuration”">​</a></h2><p>Create or edit providers in <strong>LLM API Configuration Management</strong>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Service</td><td>Translation provider</td></tr><tr><td>Model</td><td>Model name</td></tr><tr><td>Base URL</td><td>API base endpoint</td></tr><tr><td>API Key</td><td>Credential</td></tr><tr><td>Extra Parameters</td><td>Service-specific <code>extraData</code> fields</td></tr></tbody></table><p>v4.1.0 can <strong>fetch model lists</strong> from supported providers. Fetched models are merged with built-in defaults and user history, then deduplicated. A failed fetch never removes the default list.</p><h3 id="secret-logging" tabindex="-1">Secret logging <a class="header-anchor" href="#secret-logging" aria-label="Permalink to “Secret logging”">​</a></h3><p>Plugin and Server logs mask API keys, tokens, secrets and password-like fields instead of printing plaintext credentials.</p><h2 id="deepseek" tabindex="-1">DeepSeek <a class="header-anchor" href="#deepseek" aria-label="Permalink to “DeepSeek”">​</a></h2><p>v4.1.0 exposes:</p><ul><li><code>deepseek-v4-flash</code></li><li><code>deepseek-v4-pro</code></li></ul><p>Deprecated <code>deepseek-chat</code> / <code>deepseek-reasoner</code> choices are removed from the UI. Existing saved configurations are migrated as follows:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>deepseek-chat</span></span>
<span class="line"><span>→ deepseek-v4-flash + thinking=disabled</span></span>
<span class="line"><span></span></span>
<span class="line"><span>deepseek-reasoner</span></span>
<span class="line"><span>→ deepseek-v4-flash + thinking=enabled + effort=high</span></span></code></pre></div><h3 id="thinking-mode" tabindex="-1">Thinking Mode <a class="header-anchor" href="#thinking-mode" aria-label="Permalink to “Thinking Mode”">​</a></h3><p>The cost-conscious PDF translation default is:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Thinking Mode = Disabled</span></span></code></pre></div><p>When enabled:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Reasoning Effort = high / max</span></span></code></pre></div><p>Thinking Control requires a compatible actual <code>pdf2zh_next</code> runtime. Default no-thinking still translates on an older environment. The Server only stops before an API request when the user explicitly enables thinking and the runtime cannot honor it. See <a href="/en/guide/extra-params.html">Extra Parameters</a> and <a href="/en/guide/package-update.html">Translation Environment Updates</a>.</p><h2 id="qps-and-pool-size" tabindex="-1">QPS and Pool Size <a class="header-anchor" href="#qps-and-pool-size" aria-label="Permalink to “QPS and Pool Size”">​</a></h2><ul><li><strong>QPS</strong> limits translation request rate.</li><li><strong>Pool Size</strong> limits concurrent workers.</li><li><strong>Pool Size = 0 (recommended)</strong> leaves <code>pool_max_workers</code> unset so <code>pdf2zh_next</code> follows its normal QPS-based behavior.</li></ul><p>The old <code>pool size = qps × 10</code> guidance is obsolete.</p><h2 id="dual-pdf-layouts" tabindex="-1">Dual PDF Layouts <a class="header-anchor" href="#dual-pdf-layouts" aria-label="Permalink to “Dual PDF Layouts”">​</a></h2><h3 id="side-by-side-lr" tabindex="-1">Side by Side / LR <a class="header-anchor" href="#side-by-side-lr" aria-label="Permalink to “Side by Side / LR”">​</a></h3><p>Original and translated content share one page side by side.</p><p>With the upstream default order, this normally means:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Original | Translation</span></span></code></pre></div><p>Enabling <strong>Translation First</strong> reverses the order.</p><h3 id="alternating-pages-tb" tabindex="-1">Alternating Pages / TB <a class="header-anchor" href="#alternating-pages-tb" aria-label="Permalink to “Alternating Pages / TB”">​</a></h3><p>Original and translated pages alternate.</p><div class="info custom-block"><p class="custom-block-title">Historical label</p><p>Older UI/docs called TB “Top &amp; Bottom”. In the current upstream behavior it means <strong>Alternating Pages</strong>, not a same-page vertical layout.</p></div><h2 id="pdf-post-processing" tabindex="-1">PDF Post-processing <a class="header-anchor" href="#pdf-post-processing" aria-label="Permalink to “PDF Post-processing”">​</a></h2><p>v4.1.0 tracks PDF operation state to avoid invalid repeated processing:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>origin</span></span>
<span class="line"><span>→ mono / dual(LR/TB)</span></span>
<span class="line"><span>→ mono-cut / dual-cut / compare / crop-compare</span></span></code></pre></div><p><code>compare</code> and <code>crop-compare</code> are terminal results. Repeating the same operation on a terminal file is blocked before upload.</p><p>When Crop or Crop-Compare is requested for an LR dual PDF, the Server first normalizes the layout internally and then completes the real <code>dual-cut</code> / <code>crop-compare</code> operation. The internal LR→TB conversion is no longer mistaken for the final result.</p><p>See <a href="/en/guide/translation-options.html">Translation Options</a>.</p><h2 id="other-pdf2zh-next-options" tabindex="-1">Other pdf2zh_next Options <a class="header-anchor" href="#other-pdf2zh-next-options" aria-label="Permalink to “Other pdf2zh_next Options”">​</a></h2><h3 id="keep-only-actually-translated-pages" tabindex="-1">Keep Only Actually Translated Pages <a class="header-anchor" href="#keep-only-actually-translated-pages" aria-label="Permalink to “Keep Only Actually Translated Pages”">​</a></h3><p>Useful only when a page range is active, for example together with <strong>Skip Last Pages</strong>.</p><h3 id="ocr-workaround" tabindex="-1">OCR Workaround <a class="header-anchor" href="#ocr-workaround" aria-label="Permalink to “OCR Workaround”">​</a></h3><p>This primarily improves compatibility with scanned/special PDFs that already contain a text layer; it is not a complete OCR engine.</p><h3 id="enhance-compatibility" tabindex="-1">Enhance Compatibility <a class="header-anchor" href="#enhance-compatibility" aria-label="Permalink to “Enhance Compatibility”">​</a></h3><p>Enable only when you encounter rendering or text-layer problems. The upstream compatibility path may also change ordering/layout behavior.</p><h3 id="watermark-free-output" tabindex="-1">Watermark-free Output <a class="header-anchor" href="#watermark-free-output" aria-label="Permalink to “Watermark-free Output”">​</a></h3><p>Zotero PDF2zh defaults to watermark-free output and forwards that choice to <code>pdf2zh_next</code>.</p><h2 id="configuration-migration" tabindex="-1">Configuration Migration <a class="header-anchor" href="#configuration-migration" aria-label="Permalink to “Configuration Migration”">​</a></h2><p>v4.1.0 no longer overwrites user configuration from <code>.example</code> files on every startup.</p><p>The Server:</p><ul><li>preserves existing user values;</li><li>preserves unknown custom fields;</li><li>adds missing defaults;</li><li>refreshes project-managed <code>venv.json</code> package constraints while keeping additional user packages;</li><li>backs up an unparseable old config as <code>.invalid.bak</code>.</li></ul><p><code>config.toml.example</code> follows the <code>pdf2zh_next 2.9.0</code> schema while keeping Zotero PDF2zh product defaults such as DeepSeek V4, watermark-free output and <code>zh-CN</code>.</p><h2 id="server-command-line-arguments" tabindex="-1">Server Command-line Arguments <a class="header-anchor" href="#server-command-line-arguments" aria-label="Permalink to “Server Command-line Arguments”">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>--host</code></td><td><code>127.0.0.1</code></td><td>Bind address</td></tr><tr><td><code>--port</code></td><td><code>8890</code></td><td>Server port</td></tr><tr><td><code>--enable_venv</code></td><td><code>True</code></td><td>Managed translation environments</td></tr><tr><td><code>--env_tool</code></td><td><code>auto</code></td><td>Keep existing uv/conda; prefer uv for a fresh environment</td></tr><tr><td><code>--check_update</code></td><td><code>True</code></td><td>Check Server updates on startup</td></tr><tr><td><code>--update_source</code></td><td><code>gitee</code></td><td>Preferred <code>gitee</code> / <code>github</code>; both are tried</td></tr><tr><td><code>--enable_mirror</code></td><td><code>True</code></td><td>Optimize package download sources</td></tr><tr><td><code>--enable_winexe</code></td><td><code>False</code></td><td>Windows standalone exe mode</td></tr><tr><td><code>--skip_install</code></td><td><code>False</code></td><td>Disable automatic environment creation/repair</td></tr></tbody></table><p>Examples:</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Normal use</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Force conda</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env_tool=conda</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Force uv</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env_tool=uv</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Prefer GitHub for Server updates (Gitee is still tried if GitHub fails)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update_source=github</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># LAN access (advanced)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><a href="/en/guide/installation.html">Installation</a></li><li><a href="/en/guide/translation-options.html">Translation Options</a></li><li><a href="/en/guide/extra-params.html">Extra Parameters</a></li><li><a href="/en/guide/package-update.html">Translation Environment Updates</a></li></ul>`,66)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};